@spec vm_editing_spec  src=tests/specs/vm_editing_spec.lua  loc=567  cases=16
@exercises trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), midiManager (h.fm), trackerManager (h.tm)
@surface   vm:setGridSize, ec:setPos, vm:editEvent, vm:entrySignAt, cmgr:invoke, fm:dump, tm:getChannel, ec:setSelection
@harness   mk{seed.notes, seed.ccs}

# Intent
  Exercises vm editing commands against seeded tm state.

# Cases
  @case 'untempered octave column: minus negates, and refuses an octave out of range'  [harness]  @ 11-33
  @case 'delete on delay stop zeroes delay metadata'  [harness]  @ 43-67
  @case 'growNote past a same-pitch successor authors a tail past, tm clips realised'  [harness]  @ 76-96
  @case 'noteOff at the rendered tail row reopens authored endppq to util.OPEN'  [harness]  @ 104-121
  @case 'noteOff reopens a tail to util.OPEN under fractional ppqPerRow'  [harness]  @ 131-150
  @case 'placing a new note clears same-pitch coverage in other cols of the channel'  [harness]  @ 160-200
  @case 'placing a new note clamps its endppq to a same-pitch successor in another col'  [harness]  @ 208-244
  @case 'delete on pitch tied predecessor extends to next note'  [harness]  @ 252-285
  @case 'growNote past an open-tailed same-pitch predecessor does not throw'  [harness]  @ 295-319
  @case 'delete on vel inherits from a prior PA event'  [harness]  @ 325-348
  @case 'delete on pitch over a PA cell is a no-op'  [harness]  @ 354-377
  @case 'selection pitch delete leaves PAs alone'  [harness]  @ 385-413
  @case 'selection vel delete deletes PAs and resets note vels'  [harness]  @ 418-444
  @case 'edit existing PA value reads vel and persists via val'  [harness]  @ 452-477
  @case 'PA stamped under swing is reachable and deletable'  [harness]  @ 485-542
  @case 'delete on delay stop is a no-op when delay is already 0'  [harness]  @ 546-565

